# Comparison predictor ignores labels and size and always selects lower plus transpose upper.
def baseline(rs):
 hit=0
 for r in rs:
  q=r['question'];chosen=[]
  for f in q[':question/answer-fields']:
   aid=f[':answer-field/correct'][1];v=next(a[':answer/value']=='true' for a in f[':answer-field/choices'] if a[':answer/id']==aid)
   if v: chosen.append(f[':answer-field/key'])
  hit+=len(chosen)==2 and any('lower triangular' in x and '^' not in x for x in chosen) and any('upper triangular' in x and '^' in x for x in chosen)
 return hit/len(rs)
