schema=read(REPO/'generate/pipeline/pedagogical-variation.schema.json')
def validate(o,s,path='$'):
 if 'enum' in s: assert o in s['enum'],path
 t=s.get('type')
 if t=='object':
  assert isinstance(o,dict),path
  assert all(k in o for k in s.get('required',[])),path
  if s.get('additionalProperties') is False:assert set(o)<=set(s.get('properties',{})),path
  for k,v in o.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
 elif t=='array':
  assert isinstance(o,list) and len(o)>=s.get('minItems',0),path
  for i,v in enumerate(o):validate(v,s['items'],path+f'[{i}]')
 elif t=='string':assert isinstance(o,str) and len(o)>=s.get('minLength',0),path
 elif t=='integer':assert type(o) is int,path
 elif t=='number':assert type(o) in (int,float),path
 if 'minimum' in s:assert o>=s['minimum'],path
 if 'maximum' in s:assert o<=s['maximum'],path
